    const ctxs = [['temps (en min) mis par des élèves pour rentrer chez eux', 'min'], ['nombres de SMS envoyés dans la journée par des amis', ''], ['tailles (en cm) de plants de tomates', 'cm'], ['points marqués par une équipe de basket lors de ses derniers matchs', '']];
