    for (let j = 0; j < 7; j++) if (j !== i && ys[j] === ys[i]) ys[j] = ys[i] + this.randChoice([1, -1]) * this.randInt(1, 4);
    // garantir l'unicité de la valeur cherchée
    if (ys.filter(v => v === ys[i]).length !== 1) return this._h3a_Org1_tabant2(t);
