        const correctAxis = isAbscisse ? "abscisses" : "ordonnées";
        const otherAxis = isAbscisse ? "ordonnées" : "abscisses";
        const opts = this.shuffle([`Axe des ${correctAxis}`, `Axe des ${otherAxis}`, "Sur aucun axe", "À l'origine"]);

