    if (o.line === 'mediatrice') { const I = [(B[0] + C[0]) / 2, 170]; s += this._h5_ln(I[0], 190, I[0], 20, { stroke: '#dc2626', w: 1.6 }) + sq(I[0], 170, 1) + this._h5_tx(I[0] - 9, I[1] + 16, 'I', { size: 11 }); s += this._h5_ln((B[0] + I[0]) / 2, 165, (B[0] + I[0]) / 2, 175) + this._h5_ln((C[0] + I[0]) / 2, 165, (C[0] + I[0]) / 2, 175); }
